function filt(){return R.filter(r=>(!F.q||(r.bn+r.en+r.ing.map(i=>ING[i.k].join(' ')).join(' ')).toLowerCase().includes(F.q.toLowerCase()))&&(!F.cat||r.cat==F.cat)&&(!F.veg||r.veg)&&r.t<=F.max&&(!F.cui||r.cui==F.cui)).sort((a,b)=>F.sort?b.r-a.r:0)}
