function addForm(){return `<section id="add" style="margin-top:40px;background:var(--sb);border-radius:24px;padding:24px"><h2>${L?'Share your recipe':'আপনার রেসিপি শেয়ার করুন'}</h2><div class="row"><input id="nb" class="in" placeholder="${L?'Recipe name':'রেসিপির নাম'}" style="flex:1;min-width:200px"><select id="nc">${Object.keys(CATS).map(k=>`<option value="${k}">${CATS[k][L]}</option>`).join('')}</select><select id="nu"><option value="bd">${L?'Bangladeshi':'দেশি'}</option><option value="intl">${L?'International':'বিদেশি'}</option></select></div><div class="row"><input id="nt" class="in" type="number" min="1" placeholder="${L?'Time (min)':'সময় (মিনিট)'}" style="width:140px"><input id="ns" class="in" type="number" min="1" placeholder="${L?'Servings':'কত জনের'}" style="width:120px"><select id="nd"><option value="1">${t('easy')}</option><option value="2">${t('med')}</option><option value="3">${t('hard')}</option></select><label><input type="checkbox" id="nv"> ${t('vegonly')}</label></div><textarea id="ni" class="in" rows="4" style="width:100%" placeholder="${L?'Ingredients, one per line':'উপকরণ (প্রতি লাইনে একটি)'}"></textarea><br><br><textarea id="nmeth" class="in" rows="4" style="width:100%" placeholder="${L?'Method, one step per line':'রান্নার পদ্ধতি (প্রতি লাইনে একটি ধাপ)'}"></textarea><div class="row"><button class="btn" onclick="addR()">${L?'Submit':'জমা দিন'}</button><span id="nr"></span></div></section>`}
function addR(){if(SBCONF&&!SBU){sbNeed('রেসিপি জমা দিতে লগইন করুন।');return}const g=i=>document.getElementById(i),n=g('nb').value.trim(),fi=g('ni').value.split('\n').map(s=>s.trim()).filter(Boolean),st=g('nmeth').value.split('\n').map(s=>s.trim()).filter(Boolean),m=g('nr');
if(!n||!fi.length||!st.length){m.textContent=L?'Please add a name, ingredients and method.':'নাম, উপকরণ ও পদ্ধতি দিন।';return}
const r={id:'u'+Date.now(),bn:n,en:n,cat:g('nc').value,cui:g('nu').value,t:+g('nt').value||30,d:+g('nd').value,r:0,veg:g('nv').checked?1:0,e:'🍽️',c:Y,s:+g('ns').value||2,ing:[],fi,st:st.map(b=>({b,e:b,m:0})),cal:0};
MINE.push(r);R.push(r);SV('mine',MINE);if(SBU&&SBC)SBC.from('user_recipes').insert({user_id:SBU.id,title:n.slice(0,120),data:{bn:r.bn,en:r.en,cat:r.cat,cui:r.cui,t:r.t,d:r.d,veg:r.veg,s:r.s,fi:r.fi.slice(0,40),st:r.st.slice(0,40).map(x=>({b:x.b}))}}).then(({error})=>{if(error)alert('অ্যাকাউন্টে জমা দেওয়া যায়নি।')});location.hash='r-'+r.id}
