const P={about:[['আমাদের সম্পর্কে','About us'],['রঙের রান্নাঘর দেশি-বিদেশি রান্নার রেসিপি এক জায়গায় খুঁজে পাওয়ার একটি ওয়েবসাইট। এখানে রেসিপি খোঁজা, ধাপে ধাপে রান্না, সাপ্তাহিক মিল প্ল্যান ও বাজারের তালিকা তৈরি করা যায়।','Ronger Rannaghor is a place to find local and international recipes, follow step-by-step cooking, plan weekly meals and build a grocery list.']],
contact:[['যোগাযোগ','Contact'],['এই সংস্করণে কোনো ই-মেইল, ফোন নম্বর বা ঠিকানা প্রকাশ করা হয়নি। আপনার রেসিপি জানাতে চাইলে হোম পেজের নিচের রেসিপি শেয়ার ফর্ম ব্যবহার করুন।','No email, phone or address is published in this version. To send us a recipe, use the share form at the bottom of the home page.']],
faq:[['সাধারণ প্রশ্ন','FAQ'],['<p><b>প্রিয় রেসিপি কোথায় সেভ হয়?</b><br>আপনার ব্রাউজারে।</p><p><b>আমার দেওয়া রেসিপি কি অন্যরা দেখবে?</b><br>এই সংস্করণে নয়, শুধু আপনার ব্রাউজারে থাকে।</p><p><b>ক্যালরি কি নির্ভুল?</b><br>না, এগুলো আনুমানিক।</p>','<p><b>Where are favorites saved?</b><br>In your browser.</p><p><b>Can others see my recipe?</b><br>Not in this version; it stays in your browser.</p><p><b>Are calories exact?</b><br>No, they are rough estimates.</p>']],
privacy:[['গোপনীয়তা নীতি','Privacy policy'],['এখানে কোনো লগইন বা পাসওয়ার্ড নেই। প্রিয় রেসিপি, মিল প্ল্যান, নিজের রেসিপি ও রিভিউ শুধু আপনার ব্রাউজারে থাকে। (এটি আইনি নীতি নয়, সাধারণ বিবরণ।)','There is no login or password. Favorites, meal plan, your recipes and reviews stay in your browser. (A general description, not a legal policy.)']],
terms:[['ব্যবহারের শর্তাবলি','Terms of use'],['রেসিপি সাধারণ তথ্যের জন্য। অ্যালার্জি বা স্বাস্থ্য বিষয়ে ডাক্তারের পরামর্শ নিন। অন্যের কপিরাইট করা লেখা বা ছবি জমা দেবেন না। (সাধারণ বিবরণ, আইনি দলিল নয়।)','Recipes are for general information. Ask a doctor about allergies or health. Do not submit copyrighted text or photos that are not yours. (A general description, not a legal document.)']],
tips:[['রান্নার টিপস','Cooking tips'],['<p><b>লবণ বেশি হলে:</b> ঝোলে কাঁচা আলুর টুকরো বা সামান্য পানি বা দই মিশিয়ে দেখুন।</p><p><b>ভাত ঝরঝরে করতে:</b> চাল ভালো করে ধুয়ে পানি পরিমাণমতো দিন ও সেদ্ধের সময় বেশি নাড়বেন না।</p><p><b>মাংস নরম করতে:</b> রান্নার আগে দই বা কাঁচা পেঁপে বাটা মাখিয়ে রাখুন।</p><p><b>মসলা সংরক্ষণ:</b> বায়ুরোধী কৌটায় শুকনো, ঠান্ডা জায়গায় রাখুন।</p>','<p><b>Too salty:</b> add raw potato pieces, a little water or yogurt.</p><p><b>Fluffy rice:</b> wash well, use the right amount of water and avoid over-stirring.</p><p><b>Tender meat:</b> marinate with yogurt or raw papaya paste before cooking.</p><p><b>Storing spices:</b> keep in airtight jars in a cool dry place.</p>']]};
function sp(h){return `<h2>${P[h][0][L]}</h2><div class="step" style="max-width:720px">${P[h][1][L]}</div>`}
function goAdd(){const f=()=>{const e=document.getElementById('add');if(e)e.scrollIntoView({behavior:'smooth'})};if((location.hash.slice(1)||'home')=='home')f();else{location.hash='home';setTimeout(f,120)}}
function sub(){const v=document.getElementById('fe').value.trim(),m=document.getElementById('fm');if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)){m.style.color='#b3261e';m.textContent=L?'Please enter a valid email.':'সঠিক ই-মেইল দিন।';return}m.style.color='#1b6b3a';m.textContent=L?'Thanks! (Demo form: your email was not saved or sent.)':'ধন্যবাদ! (ডেমো ফর্ম: ই-মেইল সংরক্ষণ বা পাঠানো হয়নি।)';document.getElementById('fe').value=''}
